 const owned=()=>alive&&panel&&root.querySelector('.rsb-panel')===panel;
 const current=()=>owned()&&root?.isConnected!==false&&isCurrent(),$=s=>root.querySelector(s),save=()=>{if(owned())memory.set(result,clone(state));};
 const capture=(force=false)=>{if(!owned()||(!force&&!current()))return;for(const detail of root.querySelectorAll('[data-rsb-detail]'))state.open[detail.dataset.rsbDetail]=typeof detail.open==='boolean'?detail.open:detail.getAttribute('open')!==null;};
 root.innerHTML="<section class=\"rsb-panel\"><h3>From complex amplitudes to the density matrix</h3><p>The basis order is ↑, ↓, with initial state ↑. Below are the Python complex state and evolution matrix at the selected time, checked entry by entry in the outer-product ledger. Moving the trajectory slider changes the sampled time without solving the dynamics again.</p><button type=\"button\" class=\"secondary\" id=\"rsb-mid\">View the middle time sample</button><div id=\"rsb-ledger\"></div><button type=\"button\" class=\"secondary\" id=\"rsb-step\">Reveal the next outer-product step</button><details data-rsb-detail=\"phase\"><summary>Change the phase: global or relative</summary><p>This finite comparison applies a phase to the current complex state. It does not rerun evolution under the original Hamiltonian.</p><div class=\"rsb-controls\">"+select('rsb-phase-kind',"Apply the phase to",[['global',"Both components"],['relative',"Only the ↓ component"]],state.kind)+select('rsb-phase',"Phase φ",[[0,'0'],[1,'π/2'],[2,'π'],[3,'3π/2']],state.phase)+"</div><div id=\"rsb-phase-result\"></div></details><details data-rsb-detail=\"questions\"><summary>Predict, then check two questions</summary>"+questions.map((q,i)=>'<p>'+esc(q.prompt)+'</p>'+select('rsb-q'+i,"Choose a prediction",q.options,state.choices[i])+'<button type="button" class="secondary" id="rsb-check'+i+"\">Check this answer</button><p id=\"rsb-feedback"+i+'" class="rsb-feedback" role="status"></p>').join('')+"</details><label class=\"rsb-note\">Write your explanation (kept only in page memory for this result)<textarea id=\"rsb-note\" rows=\"2\" maxlength=\"2000\">"+esc(state.note)+"</textarea></label><a href=\"#classroom/spin?module=density&lesson=density-lindblad&tab=learn\">Continue to density matrices and decoherence →</a></section>";
