 const paintPhase=ledger=>{if(!ledger){$('#rsb-phase-result').innerHTML='';return;}const view=rabiPhaseComparison(ledger.state,{kind:state.kind,quarterTurns:state.phase});$('#rsb-phase-result').innerHTML=table("Amplitudes and probabilities after the phase change",["component","New amplitude","New probability"],[['↑',complex(view.state[0]),num(view.probabilities[0])],['↓',complex(view.state[1]),num(view.probabilities[1])]])+matrixHTML(view.rho)+'<p data-math-ignore>max |Δρ| = '+num(view.densityChange)+'; Bloch = ('+view.bloch.map(num).join(', ')+')</p>'+(state.kind==='global'?"<p>The global phase cancels in the outer product. The density matrix and observable probabilities remain unchanged.</p>":view.coherenceMagnitude<1e-12?"<p>Only one component is appreciably nonzero here, so this ρ cannot distinguish the relative phase. Compare a sampled time with both components present.</p>":"<p>Each population probability stays unchanged. Off-diagonal coherences and transverse Bloch components can change, so populations alone do not determine the full quantum state.</p>");};
 function paint(){if(!current())return;capture();let ledger;try{ledger=rabiStateLedger(result,state.index);$('#rsb-ledger').innerHTML=ledgerHTML(ledger,state.step);paintPhase(ledger);$('#rsb-step').disabled=!ledger;$('#rsb-step').textContent=state.step>=3?"Collapse the outer-product derivation":"Reveal the next outer-product step";restoreDetails();save();}catch(error){$('#rsb-ledger').innerHTML='<p role="alert">'+esc(error.message)+'</p>';$('#rsb-step').disabled=true;}}
