 restoreDetails();paint();const cleanup=()=>{if(!alive)return;if(owned()){capture(true);save();for(const tag of ['button','select','textarea','details'])for(const node of panel.querySelectorAll(tag)){node.onclick=null;node.oninput=null;node.onchange=null;node.ontoggle=null;}}alive=false;if(owners.get(root)===cleanup)owners.delete(root);};
